import django
from django.conf import settings
from django.db import connection

# Configure settings
if not settings.configured:
    settings.configure(
        DATABASES={
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': ':memory:',
            }
        },
        INSTALLED_APPS=[
            '__main__',
        ],
        DEBUG=True,
    )
    django.setup()

from django.db import models

class ParentModel(models.Model):
    id = models.BigIntegerField(primary_key=True)

    class Meta:
        app_label = '__main__'

class ChildModel(ParentModel):
    pass

    class Meta:
        app_label = '__main__'

# Create tables
from django.db import connection
with connection.schema_editor() as schema_editor:
    schema_editor.create_model(ParentModel)
    schema_editor.create_model(ChildModel)

def test_force_insert():
    connection.queries_log.clear()

    # Given
    child = ChildModel(id=1)

    # When
    child.save(force_insert=True)

    # Then
    queries = [q['sql'] for q in connection.queries]
    print("Queries executed:")
    for i, q in enumerate(queries):
        print(f"{i}: {q}")

    # Check for SELECT/UPDATE on parent table
    # Parent table name should be __main___parentmodel
    parent_table = '__main___parentmodel'

    # In our case, _do_update for ParentModel results in a SELECT because it has no non-pk fields.
    # If force_insert=True is respected, there should be NO SELECT or UPDATE on parent_table before the INSERT.

    update_or_select_parent = any(f"SELECT" in q and parent_table in q for q in queries) or \
                              any(f"UPDATE" in q and parent_table in q for q in queries)

    if update_or_select_parent:
        print("\nISSUE REPRODUCED: UPDATE/SELECT statement found for parent model even with force_insert=True")
        return False
    else:
        print("\nISSUE NOT REPRODUCED: No UPDATE/SELECT statement found for parent model")
        return True

if __name__ == "__main__":
    if not test_force_insert():
        exit(1)
    else:
        exit(0)
