from django.db import models, connection, NotSupportedError
from django.db.models.aggregates import Aggregate
from django.db.models import Value, F

if not settings.configured:
    settings.configure(
        DATABASES={
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': ':memory:',
            }
        },
        INSTALLED_APPS=[],
    )
    django.setup()

class GroupConcat(Aggregate):
    function = 'GROUP_CONCAT'
    template = '%(function)s(%(distinct)s %(expressions)s)'
    allow_distinct = True
    def __init__(self, expression, delimiter=None, **extra):
        if delimiter is not None:
            self.allow_distinct = False
            delimiter_expr = Value(str(delimiter))
            super().__init__(expression, delimiter_expr, **extra)
        else:
            super().__init__(expression, **extra)
    def as_sqlite(self, compiler, connection, **extra_context):
        return super().as_sql(
            compiler, connection,
            function=self.function,
            template=self.template,
            **extra_context
        )

def test_group_concat_distinct_multiple_expressions():
    print("Testing GroupConcat with DISTINCT and multiple expressions...")
    try:
        # We don't even need to run it against DB to trigger check_expression_support
        # if we call it manually or use it in a queryset.
        # Let's try to trigger check_expression_support via a dummy Aggregate object.

        gc = GroupConcat(F('field1'), F('field2'), distinct=True)
        connection.ops.check_expression_support(gc)
        print("Successfully passed check_expression_support")
    except NotSupportedError as e:
        print(f"Caught expected NotSupportedError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_group_concat_distinct_multiple_expressions()
